const getRegionClickOptions = (event: Pick<MouseEvent | React.MouseEvent, 'shiftKey' | 'metaKey' | 'ctrlKey'>): RegionClickOptions => ({
  shiftKey: event.shiftKey,
  metaKey: event.metaKey,
  ctrlKey: event.ctrlKey,
});

interface TrackGridPanelProps {
  tracks: KGTrack[];
  regions: RegionUI[];
  maxBars: number;
  timeSignature: { numerator: number; denominator: number };
  draggedTrackIndex: number | null;
  dragOverTrackIndex: number | null;
  selectedRegionId: string | null;
  projectName: string;
  onRegionCreated: (trackIndex: number, region: RegionUI, midiRegion: KGMidiRegion) => void;
  onRegionUpdated?: (regionId: string, updates: Partial<RegionUI>, expectedModelUpdates?: { startBeat: number, length: number }) => void;
  onRegionClick?: (regionId: string, options: RegionClickOptions) => void;
  onRegionLassoSelection?: (regionIds: string[], options: RegionClickOptions) => void;
  onRegionLassoCommit?: () => void;
  onOpenPianoRoll?: (regionId: string) => void;
  onOpenWaveform?: (regionId: string) => void;
  onOpenSpectrogram?: (regionId: string) => void;
  showHybridButtonForAudio?: boolean;
  showHybridButtonForMidi?: boolean;
  hybridButtonExcludedRegionIds?: string[];
  onOpenHybrid?: (regionId: string) => void;
  onExternalDropComplete?: (trackIndex: number, regionUI: RegionUI) => void;
}

const TrackGridPanel: React.FC<TrackGridPanelProps> = ({
  tracks,
  regions,
  maxBars,
  timeSignature,
  draggedTrackIndex,
  dragOverTrackIndex,
  selectedRegionId,
  projectName,
  onRegionCreated,
  onRegionUpdated,
  onRegionClick,
  onRegionLassoSelection,
  onRegionLassoCommit,
  onOpenPianoRoll,
  onOpenWaveform,
  onOpenSpectrogram,
  showHybridButtonForAudio,
  showHybridButtonForMidi,
  hybridButtonExcludedRegionIds,
  onOpenHybrid,
  onExternalDropComplete,
}) => {
  const selectedRegionIds = useProjectStore(state => state.selectedRegionIds);
  const refreshProjectState = useProjectStore(state => state.refreshProjectState);
  const bumpAudioWaveformRedrawVersion = useProjectStore(state => state.bumpAudioWaveformRedrawVersion);
  const gridContainerRef = useRef<HTMLDivElement>(null);
  const [showAudioImportModal, setShowAudioImportModal] = useState(false);
  const [previewRegionStyles, setPreviewRegionStyles] = useState<Record<string, React.CSSProperties>>({});
  const [previewRegionContentStyles, setPreviewRegionContentStyles] = useState<Record<string, RegionPreviewContentStyle>>({});
  const pendingAudioImportRef = useRef<{ barNumber: number; trackIndex: number } | null>(null);
  const isLassoSelectingRef = useRef(false);
  const isLassoShiftPressedRef = useRef(false);
  const lassoBoxRef = useRef({ startX: 0, startY: 0, endX: 0, endY: 0 });
  const [lassoRenderTick, setLassoRenderTick] = useState(0);

  const getBulkSelectedRegionIds = (primaryRegionId: string) => (
    selectedRegionIds.length > 1 && selectedRegionIds.includes(primaryRegionId)
      ? selectedRegionIds
      : [primaryRegionId]
  );

  const getBarNumberFromGridClientX = (clientX: number) => {
    if (!gridContainerRef.current) {
      return null;
    }

    const gridRect = gridContainerRef.current.getBoundingClientRect();
    const relativeX = clientX - gridRect.left;
    const barWidth = gridContainerRef.current.clientWidth / maxBars;
    const rawBar = relativeX / barWidth + 1;
    const mainContentState = KGMainContentState.instance();
    return Math.max(1, snapBarValue(rawBar, {
      enabled: mainContentState.isSnappingEnabled(),
      mode: mainContentState.getSnappingMode(),
      beatsPerBar: timeSignature.numerator,
    }));
  };

  const importAudioFileToTrackAtBar = async (
    file: File,
    track: KGTrack,
    trackIndex: number,
    barNumber: number
  ) => {
    const beatsPerBar = timeSignature.numerator;
    const fileId = KGAudioFileStorage.generateAudioFileId(file.name);
    const arrayBuffer = await file.arrayBuffer();
    const toneBuffer = new Tone.ToneAudioBuffer();

    try {
      await new Promise<void>((resolve, reject) => {
        const audioContext = Tone.getContext().rawContext as AudioContext;
        audioContext.decodeAudioData(
          arrayBuffer.slice(0),
          (decoded) => { toneBuffer.set(decoded); resolve(); },
          (err) => reject(err)
        );
      });
    } catch {
      throw new Error(getAudioImportDecodeFailureMessage(file.name));
    }

    const audioDurationSeconds = toneBuffer.duration;
    await KGAudioFileStorage.storeAudioFile(projectName, fileId, file);
    KGAudioInterface.instance().loadAudioBufferForTrack(
      track.getId().toString(),
      fileId,
      toneBuffer
    );

    const bpm = KGCore.instance().getCurrentProject().getBpm();
    const durationInBeats = audioDurationSeconds * (bpm / 60);
    const insertBeat = (barNumber - 1) * beatsPerBar;
    const lengthInBars = Math.max(1, Math.ceil(durationInBeats / beatsPerBar));
    const prevMaxBars = maxBars;
    const newMaxBars = Math.max(maxBars, barNumber + lengthInBars - 1);

    const cmd = new ImportAudioCommand(
      track.getId() as unknown as number,
      trackIndex,
      fileId,
      file.name,
      audioDurationSeconds,
      insertBeat,
      durationInBeats,
      prevMaxBars,
      newMaxBars
    );
    KGCore.instance().executeCommand(cmd);

    const created = cmd.getCreatedRegion();
    if (created && onExternalDropComplete) {
      const displayLengthInBars = Math.max(
        1,
        getAudioRegionDisplayLengthBeats(KGCore.instance().getCurrentProject(), created) / beatsPerBar
      );
      const regionUI: RegionUI = {
        id: created.getId(),
        trackId: track.getId().toString(),
        trackIndex,
        barNumber: (created.getStartFromBeat() / beatsPerBar) + 1,
        length: displayLengthInBars,
        name: created.getName(),
      };
      onExternalDropComplete(trackIndex, regionUI);
    }

    return { audioDurationSeconds };
  };

  const buildRegionUIFromImportedMidi = (
    createdRegion: KGMidiRegion,
    trackId: string,
    trackIndex: number
  ): RegionUI => {
    const beatsPerBar = timeSignature.numerator;
    return {
      id: createdRegion.getId(),
      trackId,
      trackIndex,
      barNumber: (createdRegion.getStartFromBeat() / beatsPerBar) + 1,
      length: createdRegion.getLength() / beatsPerBar,
      name: createdRegion.getName(),
    };
  };

  const importParsedMidiTrackToTarget = (
    parsedTrack: ParsedMidiImportTrack,
    targetTrackId: string,
    targetTrackIndex: number,
    dropBeat: number,
    fileStartBeat: number,
    regionName?: string
  ) => {
    const startBeat = dropBeat + (parsedTrack.startBeat - fileStartBeat);
    const lengthInBeats = parsedTrack.endBeat - parsedTrack.startBeat;
    const rawNotes = parsedTrack.notes.map(note => ({
      startBeat: note.startBeat - parsedTrack.startBeat,
      endBeat: note.endBeat - parsedTrack.startBeat,
      pitch: note.pitch,
      velocity: note.velocity,
    }));

    const command = new ImportMidiClipCommand(
      targetTrackId,
      targetTrackIndex,
      startBeat,
      lengthInBeats,
      rawNotes,
      regionName ?? `${parsedTrack.name} Region`
    );
    KGCore.instance().executeCommand(command);
    return command.getCreatedRegion();
  };

  const importMidiFileToTrackAtBar = async (
    file: File,
    track: KGTrack,
    trackIndex: number,
    barNumber: number
  ) => {
    if (track.getType() !== TrackType.MIDI) {
      await showAlert('MIDI files can only be imported into MIDI tracks. Please drop them onto a MIDI track.');
      return false;
    }

    const arrayBuffer = await file.arrayBuffer();
    const parsedMidi = parseMidiImportData(new Uint8Array(arrayBuffer));
    if (parsedMidi.tracks.length === 0) {
      throw new Error(`"${file.name}" does not contain any note data.`);
    }

    const beatsPerBar = timeSignature.numerator;
    const dropBeat = (barNumber - 1) * beatsPerBar;
    const importedRegions: Array<{ trackIndex: number; region: KGMidiRegion }> = [];

    const primaryRegion = importParsedMidiTrackToTarget(
      parsedMidi.tracks[0],
      track.getId().toString(),
      trackIndex,
      dropBeat,
      parsedMidi.fileStartBeat,
      file.name
    );
    if (primaryRegion) {
      importedRegions.push({ trackIndex, region: primaryRegion });
    }

    for (let index = 1; index < parsedMidi.tracks.length; index += 1) {
      const parsedTrack = parsedMidi.tracks[index];
      const addTrackCommand = new AddTrackCommand(undefined, parsedTrack.name, parsedTrack.suggestedInstrument);
      KGCore.instance().executeCommand(addTrackCommand);

      const appendedTrack = addTrackCommand.getCreatedTrack();
      if (!appendedTrack) {
        continue;
      }

      const insertionIndex = trackIndex + index;
      const appendedTrackIndex = appendedTrack.getTrackIndex();
      if (appendedTrackIndex !== insertionIndex) {
        KGCore.instance().executeCommand(new ReorderTracksCommand(appendedTrackIndex, insertionIndex));
      }

      const createdTrack = KGCore.instance().getCurrentProject().getTracks()[insertionIndex];
      const createdRegion = importParsedMidiTrackToTarget(
        parsedTrack,
        createdTrack.getId().toString(),
        insertionIndex,
        dropBeat,
        parsedMidi.fileStartBeat
      );

      if (createdRegion) {
        importedRegions.push({ trackIndex: insertionIndex, region: createdRegion });
      }
    }

    const importedTrackEndBeat = Math.max(
      ...parsedMidi.tracks.map(parsedTrack => dropBeat + (parsedTrack.endBeat - parsedMidi.fileStartBeat))
    );
    const requiredBars = Math.ceil(importedTrackEndBeat / beatsPerBar);
    const currentProject = KGCore.instance().getCurrentProject();
    if (requiredBars > currentProject.getMaxBars()) {
      currentProject.setMaxBars(requiredBars);
    }

    refreshProjectState();

    if (importedRegions.length > 0 && onExternalDropComplete) {
      const primaryImportedRegion = importedRegions[0];
      onExternalDropComplete(
        primaryImportedRegion.trackIndex,
        buildRegionUIFromImportedMidi(
          primaryImportedRegion.region,
          primaryImportedRegion.region.getTrackId(),
          primaryImportedRegion.trackIndex
        )
      );
    }

    return true;
  };

  const startLassoSelection = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    if (KGMainContentState.instance().getActiveTool() !== 'pointer') return;
    if (isModifierKeyPressed(e)) return;
    if (!(e.target instanceof HTMLElement)) return;
    if (!e.target.closest('.track-grid')) return;
    if (e.target.closest('.track-region')) return;

    const rect = gridContainerRef.current?.getBoundingClientRect();
    if (!rect) return;

    const startX = e.clientX - rect.left;
    const startY = e.clientY - rect.top;

    isLassoSelectingRef.current = true;
    isLassoShiftPressedRef.current = e.shiftKey;
    lassoBoxRef.current = { startX, startY, endX: startX, endY: startY };
    setLassoRenderTick(prev => prev + 1);

    document.addEventListener('mousemove', handleLassoMouseMove);
    document.addEventListener('mouseup', handleLassoMouseUp);
  };

  const handleLassoMouseMove = (e: MouseEvent) => {
    if (!isLassoSelectingRef.current || !gridContainerRef.current) return;

    const rect = gridContainerRef.current.getBoundingClientRect();
    lassoBoxRef.current = {
      ...lassoBoxRef.current,
      endX: e.clientX - rect.left,
      endY: e.clientY - rect.top,
    };
    setLassoRenderTick(prev => prev + 1);
  };

  const handleLassoMouseUp = () => {
    if (!isLassoSelectingRef.current || !gridContainerRef.current) return;

    const { startX, startY, endX, endY } = lassoBoxRef.current;
    const left = Math.min(startX, endX);
    const top = Math.min(startY, endY);
    const right = Math.max(startX, endX);
    const bottom = Math.max(startY, endY);
    const isClick = (right - left < PIANO_ROLL_CONSTANTS.DRAG_THRESHOLD)
      && (bottom - top < PIANO_ROLL_CONSTANTS.DRAG_THRESHOLD);

    if (isClick) {
      if (!isLassoShiftPressedRef.current) {
        onRegionLassoSelection?.([], getRegionClickOptions({ shiftKey: false, metaKey: false, ctrlKey: false }));
      }
    } else {
      const containerWidth = gridContainerRef.current.clientWidth;
      const barWidth = containerWidth > 0 ? containerWidth / maxBars : 0;
      const releasePointX = endX;
      const releasePointY = endY;
      const intersectedRegions = barWidth > 0
        ? regions.filter(region => {
            const regionLeft = (region.barNumber - 1) * barWidth;
            const regionRight = regionLeft + (region.length * barWidth);
            const regionTop = region.trackIndex * 120;
            const regionBottom = regionTop + 120;

            return !(
              regionRight < left ||
              regionLeft > right ||
              regionBottom < top ||
              regionTop > bottom
            );
          })
        : [];

      const releaseRegionIndex = intersectedRegions.findIndex(region => {
        const regionLeft = (region.barNumber - 1) * barWidth;
        const regionRight = regionLeft + (region.length * barWidth);
        const regionTop = region.trackIndex * 120;
        const regionBottom = regionTop + 120;

        return releasePointX >= regionLeft
          && releasePointX <= regionRight
          && releasePointY >= regionTop
          && releasePointY <= regionBottom;
      });

      const intersectedRegionIds = intersectedRegions.map(region => region.id);
      if (intersectedRegionIds.length > 0) {
        const primaryRegionIndex = releaseRegionIndex > -1
          ? releaseRegionIndex
          : intersectedRegions.reduce((closestIndex, region, index, allRegions) => {
              const regionLeft = (region.barNumber - 1) * barWidth;
              const regionRight = regionLeft + (region.length * barWidth);
              const regionTop = region.trackIndex * 120;
              const regionBottom = regionTop + 120;
              const regionCenterX = (regionLeft + regionRight) / 2;
              const regionCenterY = (regionTop + regionBottom) / 2;
              const regionDistance = Math.hypot(releasePointX - regionCenterX, releasePointY - regionCenterY);

              const closestRegion = allRegions[closestIndex];
              const closestLeft = (closestRegion.barNumber - 1) * barWidth;
              const closestRight = closestLeft + (closestRegion.length * barWidth);
              const closestTop = closestRegion.trackIndex * 120;
              const closestBottom = closestTop + 120;
              const closestCenterX = (closestLeft + closestRight) / 2;
              const closestCenterY = (closestTop + closestBottom) / 2;
              const closestDistance = Math.hypot(releasePointX - closestCenterX, releasePointY - closestCenterY);

              return regionDistance < closestDistance ? index : closestIndex;
            }, 0);

        const [primaryRegionId] = intersectedRegionIds.splice(primaryRegionIndex, 1);
        intersectedRegionIds.push(primaryRegionId);
      }

      onRegionLassoSelection?.(intersectedRegionIds, {
        shiftKey: isLassoShiftPressedRef.current,
        metaKey: false,
        ctrlKey: false,
      });
      onRegionLassoCommit?.();
    }

    isLassoSelectingRef.current = false;
    setLassoRenderTick(prev => prev + 1);
    document.removeEventListener('mousemove', handleLassoMouseMove);
    document.removeEventListener('mouseup', handleLassoMouseUp);
  };

  useEffect(() => {
    return () => {
      document.removeEventListener('mousemove', handleLassoMouseMove);
      document.removeEventListener('mouseup', handleLassoMouseUp);
    };
  }, []);

  // Utility function to create a region at a specific position
  const createRegionAtPosition = async (e: React.MouseEvent<HTMLDivElement>, trackIndex: number) => {
    // Get the grid container element
    const gridContainer = e.currentTarget.closest('.grid-container');
    if (!gridContainer) return;
    
    // Get the grid container's bounding rectangle
    const gridRect = gridContainer.getBoundingClientRect();
    
    // Calculate the relative X position within the grid
    const relativeX = e.clientX - gridRect.left;
    
    // Calculate the width of each bar
    const barWidth = gridContainer.clientWidth / maxBars;
    
    // Calculate which bar was clicked (0-indexed)
    const barIndex = Math.floor(relativeX / barWidth);
    
    // Add 1 to convert to 1-indexed bar number
    const barNumber = barIndex + 1;
    
    // Get the track and its ID
    const track = tracks[trackIndex];
    const trackId = track.getId().toString();

    // For audio tracks, show the file import modal instead of creating a blank region
    if (track.getType() === TrackType.Wave) {
      const mainContentState = KGMainContentState.instance();
      const rawBar = relativeX / barWidth + 1;
      const snappedBarNumber = Math.max(1, snapBarValue(rawBar, {
        enabled: mainContentState.isSnappingEnabled(),
        mode: mainContentState.getSnappingMode(),
        beatsPerBar: timeSignature.numerator,
      }));
      pendingAudioImportRef.current = { barNumber: snappedBarNumber, trackIndex };
      setShowAudioImportModal(true);
      return;
    }

    if (DEBUG_MODE.TRACK_GRID_PANEL) {
      console.log(`Creating region on track ${trackIndex + 1}, bar ${barNumber}`);
    }
    
    // Get beats per bar from the time signature
    const beatsPerBar = timeSignature.numerator;
    
    // Check for overlapping regions before creating a new one
    const newRegionStartBeat = (barNumber - 1) * beatsPerBar;
    const newRegionEndBeat = newRegionStartBeat + beatsPerBar - 1;
    
    const existingRegions = track.getRegions();
    const hasOverlap = existingRegions.some(region => {
      const existingStart = region.getStartFromBeat();
      const existingEnd = existingStart + region.getLength() - 1;
      return newRegionStartBeat <= existingEnd && newRegionEndBeat >= existingStart;
    });
    
    if (hasOverlap) {
      if (DEBUG_MODE.TRACK_GRID_PANEL) {
        console.log(`Cannot create region at bar ${barNumber}: overlaps with existing region`);
      }
      await showAlert('Cannot create region: overlaps with existing region');
      return; // Don't create the region if it overlaps
    }
    
    // Create and execute the region creation command
    const command = CreateRegionCommand.fromBarCoordinates(
      trackId,
      trackIndex,
      barNumber,
      1, // Default to 1 bar length
      beatsPerBar,
      generateNewRegionName(trackId)
    );
    
    KGCore.instance().executeCommand(command);
    
    // Get the created region for the UI callback
    const createdRegion = command.getCreatedRegion();
    if (createdRegion) {
      // Create the region UI object for the parent component
      const newRegionUI: RegionUI = {
        id: createdRegion.getId(),
        trackId: trackId,
        trackIndex,
        barNumber,
        length: 1,
        name: createdRegion.getName()
      };
      
      // Notify parent about the new region (for UI state updates)
      onRegionCreated(trackIndex, newRegionUI, createdRegion);
    }
  };

  // Handle audio file import after the user picks a file from the modal
  const handleAudioFileImport = async (file: File) => {
    setShowAudioImportModal(false);
    const pending = pendingAudioImportRef.current;
    if (!pending) return;
    pendingAudioImportRef.current = null;

    const { barNumber, trackIndex } = pending;
    const track = tracks[trackIndex];
    if (!track) return;

    try {
      const { audioDurationSeconds } = await importAudioFileToTrackAtBar(file, track, trackIndex, barNumber);

      if (DEBUG_MODE.TRACK_GRID_PANEL) {
        console.log(`[TrackGrid] Imported audio "${file.name}" to track ${trackIndex}, bar ${barNumber}, ${audioDurationSeconds.toFixed(2)}s`);
      }
    } catch (err) {
      console.error('[TrackGrid] Audio import from click failed:', err);
      await showAlert(err instanceof Error ? err.message : `Failed to import "${file.name}".`);
    }
  };

  const handleLocalFileDrop = async (e: React.DragEvent<HTMLDivElement>, trackIndex: number) => {
    const file = e.dataTransfer.files?.[0];
    if (!file) {
      return;
    }

    const track = tracks[trackIndex];
    if (!track) {
      return;
    }

    const barNumber = getBarNumberFromGridClientX(e.clientX);
    if (barNumber === null) {
      return;
    }

    if (isAcceptedAudioImportFile(file)) {
      if (track.getType() !== TrackType.Wave) {
        await showAlert('Audio files can only be imported into audio tracks. Please drop them onto an audio track.');
        return;
      }

      try {
        const { audioDurationSeconds } = await importAudioFileToTrackAtBar(file, track, trackIndex, barNumber);

        if (DEBUG_MODE.TRACK_GRID_PANEL) {
          console.log(`[TrackGrid] Imported dropped audio "${file.name}" to track ${trackIndex}, bar ${barNumber}, ${audioDurationSeconds.toFixed(2)}s`);
        }
      } catch (err) {
        console.error('[TrackGrid] Audio import from file drop failed:', err);
        await showAlert(err instanceof Error ? err.message : `Failed to import "${file.name}".`);
      }
      return;
    }

    if (isAcceptedMidiImportFile(file)) {
      try {
        const didImport = await importMidiFileToTrackAtBar(file, track, trackIndex, barNumber);

        if (didImport && DEBUG_MODE.TRACK_GRID_PANEL) {
          console.log(`[TrackGrid] Imported dropped MIDI "${file.name}" to track ${trackIndex}, bar ${barNumber}`);
        }
      } catch (err) {
        console.error('[TrackGrid] MIDI import from file drop failed:', err);
        await showAlert(err instanceof Error ? err.message : `Failed to import "${file.name}".`);
      }
      return;
    }

    await showAlert(
      `Invalid file type. Please select a file with one of these extensions: ${[
        ...AUDIO_IMPORT_ACCEPTED_TYPES,
        ...MIDI_IMPORT_ACCEPTED_TYPES,
      ].join(', ')}`
    );
  };

  // Handle double click on track grid to create region
  const handleTrackGridDoubleClick = (e: React.MouseEvent<HTMLDivElement>, trackIndex: number) => {
    // Only allow double-click creation in pointer mode
    if (KGMainContentState.instance().getActiveTool() === 'pencil') {
      return;
    }
    createRegionAtPosition(e, trackIndex);
  };

  // Handle single click on track grid for pencil mode or modifier-click on empty space.
  const handleTrackGridClick = (e: React.MouseEvent<HTMLDivElement>, trackIndex: number) => {
    if (!(e.target instanceof HTMLElement)) {
      return;
    }

    const clickedInsideRegion = e.target.closest('.track-region');
    if (clickedInsideRegion) {
      return;
    }

    const isPencilMode = KGMainContentState.instance().getActiveTool() === 'pencil';
    if (!isPencilMode && !isModifierKeyPressed(e)) {
      return;
    }

    createRegionAtPosition(e, trackIndex);
  };

  // Handle region resize during drag
  const handleRegionResize = (regionId: string, newBarNumber: number, newLength: number) => {
    // This is just for live visual updates, we don't update the model yet
    if (DEBUG_MODE.TRACK_GRID_PANEL) {
      console.log(`Resizing region ${regionId} to barNumber ${newBarNumber}, length ${newLength}`);
    }
  };

  // Handle region resize end
  const handleRegionResizeEnd = async (regionId: string, finalBarNumber: number, finalLength: number) => {
    // Now we update the model with the final rounded values
    if (DEBUG_MODE.TRACK_GRID_PANEL) {
      console.log(`Finished resizing region ${regionId} to barNumber ${finalBarNumber}, length ${finalLength}`);
    }

    // Find the region
    const region = regions.find(r => r.id === regionId);
    if (!region) return;

    // Calculate new start and length in beats
    const beatsPerBar = timeSignature.numerator;
    let clampedBarNumber = finalBarNumber;
    let clampedLength = finalLength;

    // Find the track that contains this region
    const track = tracks.find(t => t.getId().toString() === region.trackId);
    if (!track) return;

    // Update the region in the track's model
    const trackRegions = track.getRegions();
    const coreRegion = trackRegions.find(r => r.getId() === regionId);

    if (coreRegion) {
      const oldStartBeat = coreRegion.getStartFromBeat();
      const oldBarNumber = region.barNumber;
      const bulkRegionIds = getBulkSelectedRegionIds(regionId);
      const isBulkEdit = bulkRegionIds.length > 1;

      if (DEBUG_MODE.TRACK_GRID_PANEL) {
        console.log(`Updating KGRegion model - Before: startBeat=${oldStartBeat}, length=${coreRegion.getLength()}`);
        console.log(`Bar numbers - old: ${oldBarNumber}, new: ${finalBarNumber}`);
      }

      // Clamp audio region resize to audio file boundaries for single-region editing only.
      let newClipStartOffsetSeconds: number | undefined;
      if (!isBulkEdit && coreRegion instanceof KGAudioRegion) {
        const bpm = KGCore.instance().getCurrentProject().getBpm();
        const secondsPerBeat = 60 / bpm;
        const clipOffset = coreRegion.getClipStartOffsetSeconds();
        const audioDuration = coreRegion.getAudioDurationSeconds();
        const mainContentState = KGMainContentState.instance();

        // Left edge changed — calculate new clip offset
        if (clampedBarNumber !== oldBarNumber) {
          const newStartBeat = (clampedBarNumber - 1) * beatsPerBar;
          const beatDelta = newStartBeat - oldStartBeat;
          const secondsDelta = beatDelta * secondsPerBeat;
          const unclampedClipOffset = clipOffset + secondsDelta;

          if (unclampedClipOffset < 0) {
            // Dragged past audio start — snap to earliest allowed position
            const maxLeftExtensionBeats = clipOffset / secondsPerBeat;
            const minStartBeat = oldStartBeat - maxLeftExtensionBeats;
            clampedBarNumber = snapBarValue((minStartBeat / beatsPerBar) + 1, {
              enabled: mainContentState.isSnappingEnabled(),
              mode: mainContentState.getSnappingMode(),
              beatsPerBar,
            }, 'ceil');
            const oldEndBarNumber = oldBarNumber + (coreRegion.getLength() / beatsPerBar);
            clampedLength = oldEndBarNumber - clampedBarNumber;
            newClipStartOffsetSeconds = 0;
          } else {
            newClipStartOffsetSeconds = Math.min(unclampedClipOffset, audioDuration);
          }
        }

        // Right edge — clamp length so it doesn't exceed remaining audio
        const effectiveClipOffset = newClipStartOffsetSeconds ?? clipOffset;
        const maxDurationSeconds = audioDuration - effectiveClipOffset;
        const maxLengthBars = (maxDurationSeconds / secondsPerBeat) / beatsPerBar;
        if (clampedLength > maxLengthBars) {
          clampedLength = snapBarValue(maxLengthBars, {
            enabled: mainContentState.isSnappingEnabled(),
            mode: mainContentState.getSnappingMode(),
            beatsPerBar,
          }, 'floor');
          if (clampedLength < REGION_CONSTANTS.MIN_REGION_LENGTH) {
            clampedLength = REGION_CONSTANTS.MIN_REGION_LENGTH;
          }
        }
      }

      const newStartBeat = (clampedBarNumber - 1) * beatsPerBar;
      const newLengthInBeats = clampedLength * beatsPerBar;

      // Use command pattern to update the region position and length (note adjustments handled inside command)
      try {
        if (isBulkEdit) {
          const command = new ResizeMultipleRegionsCommand(
            regionId,
            clampedBarNumber !== oldBarNumber ? 'start' : 'end',
            newStartBeat - oldStartBeat,
            newLengthInBeats - coreRegion.getLength(),
            bulkRegionIds
          );

          KGCore.instance().executeCommand(command, { rethrow: true });
          refreshProjectState();
          return;
        }

        const command = ResizeRegionCommand.fromBarCoordinates(
          regionId,
          clampedBarNumber,
          clampedLength,
          timeSignature,
          newClipStartOffsetSeconds
        );

        KGCore.instance().executeCommand(command, { rethrow: true });

        if (DEBUG_MODE.TRACK_GRID_PANEL) {
          console.log(`Executed ResizeRegionCommand: region ${regionId} resized using command pattern`);

          // Verify the command worked
          const updatedRegion = track.getRegions().find(r => r.getId() === regionId);
          console.log(`Verified region in track: ${updatedRegion ? 'found' : 'not found'}, startBeat=${updatedRegion?.getStartFromBeat()}, length=${updatedRegion?.getLength()}`);
        }
      } catch (error) {
        console.error('Error resizing region:', error);
        await showAlert(error instanceof Error ? error.message : 'Unable to resize the selected regions.');
        return;
      }

      // Update the region in the parent component with expected model values
      if (onRegionUpdated) {
        onRegionUpdated(
          regionId,
          { barNumber: clampedBarNumber, length: clampedLength },
          { startBeat: newStartBeat, length: newLengthInBeats }
        );
      }
    }
  };

  // Handle region drag during movement
  const handleRegionDrag = (regionId: string, newBarNumber: number, trackIndex: number) => {
    // This is just for live visual updates, we don't update the model yet
    if (DEBUG_MODE.TRACK_GRID_PANEL) {
      console.log(`Dragging region ${regionId} to barNumber ${newBarNumber}, trackIndex ${trackIndex}`);
    }
    
    // We don't need to update any temporary state in the parent component anymore
    // The region will follow the mouse directly using transform in the TrackGridItem component
  };

  // Handle region drag end
  const handleRegionDragEnd = async (regionId: string, finalBarNumber: number, finalTrackIndex: number) => {
    // Now we update the model with the final rounded values
    if (DEBUG_MODE.TRACK_GRID_PANEL) {
      console.log(`Finished dragging region ${regionId} to barNumber ${finalBarNumber}, trackIndex ${finalTrackIndex}`);
    }
    
    // Find the region
    const region = regions.find(r => r.id === regionId);
    if (!region) return;
    const bulkRegionIds = getBulkSelectedRegionIds(regionId);
    const isBulkEdit = bulkRegionIds.length > 1;
    const effectiveTrackIndex = isBulkEdit ? region.trackIndex : finalTrackIndex;

    if (finalBarNumber === region.barNumber && effectiveTrackIndex === region.trackIndex) {
      if (DEBUG_MODE.TRACK_GRID_PANEL) {
        console.log(`Skipping no-op move for region ${regionId}`);
      }
      return;
    }
    
    // Get the target track
    const targetTrack = tracks[effectiveTrackIndex];
    if (!targetTrack) return;

    // Block cross-type region moves (MIDI <-> Audio)
    const sourceTrack = tracks.find(t => {
      return t.getRegions().some(r => r.getId() === regionId);
    });
    const movedRegionWasAudio = sourceTrack?.getRegions().find(r => r.getId() === regionId) instanceof KGAudioRegion;
    if (sourceTrack && sourceTrack.getType() !== targetTrack.getType()) {
      // Snap back — don't execute the move
      if (DEBUG_MODE.TRACK_GRID_PANEL) {
        console.log(`Blocked cross-type move: ${sourceTrack.getType()} region cannot move to ${targetTrack.getType()} track`);
      }
      return;
    }

    // Use command pattern to move the region
    try {
      if (isBulkEdit) {
        const oldStartBeat = (region.barNumber - 1) * timeSignature.numerator;
        const newStartBeat = (finalBarNumber - 1) * timeSignature.numerator;
        const command = new MoveMultipleRegionsCommand(
          regionId,
          newStartBeat - oldStartBeat,
          bulkRegionIds
        );

        KGCore.instance().executeCommand(command, { rethrow: true });
        refreshProjectState();
        if (bulkRegionIds.some(selectedId => {
          const candidate = tracks.flatMap(track => track.getRegions()).find(region => region.getId() === selectedId);
          return candidate instanceof KGAudioRegion;
        })) {
          bumpAudioWaveformRedrawVersion();
        }
        return;
      }

      const command = MoveRegionCommand.fromBarCoordinates(
        regionId,
        finalBarNumber,
        targetTrack.getId().toString(),
        effectiveTrackIndex,
        timeSignature
      );
      
      KGCore.instance().executeCommand(command, { rethrow: true });

      // Copy audio buffer to target track if this is a cross-track audio region move
      if (sourceTrack && targetTrack && sourceTrack.getId() !== targetTrack.getId()) {
        const coreRegion = targetTrack.getRegions().find(r => r.getId() === regionId);
        if (coreRegion?.getCurrentType() === 'KGAudioRegion') {
          const audioRegion = coreRegion as unknown as KGAudioRegion;
          KGAudioInterface.instance().copyAudioBufferBetweenTracks(
            sourceTrack.getId().toString(),
            targetTrack.getId().toString(),
            audioRegion.getAudioFileId()
          );
        }
      }

      if (DEBUG_MODE.TRACK_GRID_PANEL) {
        console.log(`Executed MoveRegionCommand: region ${regionId} moved using command pattern`);

        // Verify the command worked
        const movedRegion = command.getTargetRegion();
        console.log(`Verified region: ${movedRegion ? 'found' : 'not found'}, startBeat=${movedRegion?.getStartFromBeat()}, trackId=${movedRegion?.getTrackId()}`);
      }
      if (movedRegionWasAudio) {
        bumpAudioWaveformRedrawVersion();
      }
    } catch (error) {
      console.error('Error moving region:', error);
      await showAlert(error instanceof Error ? error.message : 'Unable to move the selected regions.');
      return;
    }
    
    // Calculate new start in beats for UI update
    const beatsPerBar = timeSignature.numerator;
    const startBeat = (finalBarNumber - 1) * beatsPerBar;
    
    // Update the region in the parent component with expected model values
    if (onRegionUpdated) {
      // Find the updated region to get its length
      const updatedTrack = tracks[effectiveTrackIndex];
      const updatedRegions = updatedTrack.getRegions();
      const updatedRegion = updatedRegions.find(r => r.getId() === regionId);
      
      onRegionUpdated(
        regionId, 
        { 
          trackId: targetTrack.getId().toString(), 
          trackIndex: effectiveTrackIndex, 
          barNumber: finalBarNumber 
        },
        { 
          startBeat, 
          length: updatedRegion ? updatedRegion.getLength() : 0 
        }
      );
    }
  };

  // Handle fine-move end — execute MoveRegionCommand with float-precision beat position
  const handleRegionFineMoveEnd = async (regionId: string, deltaInBars: number) => {
    const region = regions.find(r => r.id === regionId);
    if (!region) return;
    const track = tracks.find(t => t.getId().toString() === region.trackId);
    if (!track) return;
    const coreRegion = track.getRegions().find(r => r.getId() === regionId);
    if (!coreRegion) return;
    const bulkRegionIds = getBulkSelectedRegionIds(regionId);
    const isBulkEdit = bulkRegionIds.length > 1;

    const beatsPerBar = timeSignature.numerator;
    const newStartFromBeat = Math.max(0, coreRegion.getStartFromBeat() + deltaInBars * beatsPerBar);
    if (newStartFromBeat === coreRegion.getStartFromBeat()) return;

    try {
      if (isBulkEdit) {
        const command = new MoveMultipleRegionsCommand(
          regionId,
          deltaInBars * beatsPerBar,
          bulkRegionIds
        );
        KGCore.instance().executeCommand(command, { rethrow: true });
        refreshProjectState();
        if (bulkRegionIds.some(selectedId => {
          const candidate = tracks.flatMap(track => track.getRegions()).find(region => region.getId() === selectedId);
          return candidate instanceof KGAudioRegion;
        })) {
          bumpAudioWaveformRedrawVersion();
        }
        return;
      }

      // Use constructor directly (NOT fromBarCoordinates) to preserve float precision
      const command = new MoveRegionCommand(
        regionId,
        newStartFromBeat,
        track.getId().toString(),
        region.trackIndex
      );
      KGCore.instance().executeCommand(command, { rethrow: true });
      if (coreRegion instanceof KGAudioRegion) {
        bumpAudioWaveformRedrawVersion();
      }

      if (DEBUG_MODE.TRACK_GRID_PANEL) {
        console.log(`Fine-moved region ${regionId}: startFromBeat=${newStartFromBeat}`);
      }

      const newBarNumber = newStartFromBeat / beatsPerBar + 1;
      onRegionUpdated?.(
        regionId,
        { barNumber: newBarNumber, trackId: region.trackId, trackIndex: region.trackIndex },
        { startBeat: newStartFromBeat, length: coreRegion.getLength() }
      );
    } catch (error) {
      console.error('Error executing fine-move:', error);
      await showAlert(error instanceof Error ? error.message : 'Unable to move the selected regions.');
    }
  };

  // Handle region click
  const handleRegionClick = (regionId: string, options: RegionClickOptions) => {
    if (DEBUG_MODE.TRACK_GRID_PANEL) {
      console.log(`Region clicked in panel: ${regionId}`);
    }
    
    // Find the region
    const region = regions.find(r => r.id === regionId);
    if (!region) return;
    
    // Find the track that contains this region
    const track = tracks.find(t => t.getId().toString() === region.trackId);
    if (!track) return;
    
    // Find the region in the track's model
    const trackRegions = track.getRegions();
    const midiRegion = trackRegions.find(r => r.getId() === regionId) as KGMidiRegion | undefined;
    
    if (midiRegion && DEBUG_MODE.TRACK_GRID_PANEL) {
      console.log(`Found region in model: ${midiRegion.getId()}, trackId=${midiRegion.getTrackId()}, name=${midiRegion.getName()}`);
    }
    
    // Notify parent about the click
    if (onRegionClick) {
      onRegionClick(regionId, options);
    }
  };

  // Handle external K.G.One clip drop onto a track row
  const handleExternalDrop = async (e: React.DragEvent<HTMLDivElement>, trackIndex: number) => {
    const raw = e.dataTransfer.getData('application/kgone-clip');
    if (!raw) return;

    let dropData: { midiUrl?: string; audioUrl: string; audioDurationSeconds: number; audioFileName: string };
    try {
      dropData = JSON.parse(raw);
    } catch {
      console.error('[KGOne] Invalid drop data');
      return;
    }

    const barNumber = getBarNumberFromGridClientX(e.clientX);
    if (barNumber === null) return;

    const track = tracks[trackIndex];
    if (!track) return;

    const beatsPerBar = timeSignature.numerator;

    try {
      if (track.getType() === TrackType.MIDI) {
        if (!dropData.midiUrl) {
          await showAlert(
            'This audio clip can only be imported into an audio track.\n' +
            'Please drag it onto an audio track instead.'
          );
          return;
        }
        // ── MIDI track: fetch MIDI file and create a KGMidiRegion ──────────
        const midiResp = await fetch(dropData.midiUrl);
        if (!midiResp.ok) throw new Error(`MIDI fetch failed (${midiResp.status})`);
        const buf = await midiResp.arrayBuffer();
        const { notes, totalBeats } = parseMidiFirstTrackNotes(new Uint8Array(buf));
        const lengthInBars = Math.max(1, Math.ceil(totalBeats / beatsPerBar));

        const cmd = ImportMidiClipCommand.fromBarCoordinates(
          track.getId().toString(),
          trackIndex,
          barNumber,
          lengthInBars,
          beatsPerBar,
          notes,
          'KGOne Clip'
        );
        KGCore.instance().executeCommand(cmd);

        const created = cmd.getCreatedRegion();
        if (created && onExternalDropComplete) {
          const displayLengthInBars = Math.max(
            1,
            getAudioRegionDisplayLengthBeats(KGCore.instance().getCurrentProject(), created as unknown as KGAudioRegion) / beatsPerBar
          );
          const regionUI: RegionUI = {
            id: created.getId(),
            trackId: track.getId().toString(),
            trackIndex,
            barNumber,
            length: displayLengthInBars,
            name: created.getName(),
          };
          onExternalDropComplete(trackIndex, regionUI);
        }

        if (DEBUG_MODE.TRACK_GRID_PANEL) {
          console.log(`[KGOne] Imported MIDI clip to track ${trackIndex}, bar ${barNumber}, ${notes.length} notes`);
        }

      } else if (track.getType() === TrackType.Wave) {
        // ── Audio track: save blob to OPFS and create a KGAudioRegion ──────
        const blob = await fetch(dropData.audioUrl).then(r => r.blob());
        const audioFile = new File([blob], dropData.audioFileName, { type: 'audio/wav' });
        const { audioDurationSeconds } = await importAudioFileToTrackAtBar(audioFile, track, trackIndex, barNumber);

        if (DEBUG_MODE.TRACK_GRID_PANEL) {
          console.log(`[KGOne] Imported audio clip to track ${trackIndex}, bar ${barNumber}, ${audioDurationSeconds.toFixed(2)}s`);
        }
      }
    } catch (err) {
      console.error('[KGOne] Drop import failed:', err);
    }
  };

  const handleChordRegionDrop = async (e: React.DragEvent<HTMLDivElement>, trackIndex: number) => {
    const raw = e.dataTransfer.getData(CHORD_REGION_IMPORT_MIME_TYPE);
    if (!raw) {
      await showAlert('Unable to import the chord progression from this drag operation. Please try again.');
      return;
    }

    let payload: ChordRegionImportPayload;
    try {
      payload = JSON.parse(raw) as ChordRegionImportPayload;
    } catch {
      await showAlert('Unable to read the dragged chord progression. Please try again.');
      return;
    }

    const track = tracks[trackIndex];
    if (!track) {
      await showAlert('Unable to find the destination track for this import.');
      return;
    }

    if (track.getType() !== TrackType.MIDI) {
      await showAlert('Chord regions can only be converted into MIDI tracks. Please drop them onto a MIDI track.');
      return;
    }

    const chordRegionIds = Array.from(new Set(payload.selectedRegionIds ?? []));
    const chordRegions = chordRegionIds.map(regionId => {
      const region = KGCore.instance().getCurrentProject().getGlobalTracks()
        .flatMap(globalTrack => globalTrack.getRegions())
        .find(candidate => candidate.getId() === regionId);
      return region instanceof KGChordRegion ? region : null;
    }).filter((region): region is KGChordRegion => region !== null);

    if (chordRegions.length === 0) {
      await showAlert('No chord regions were available to import. Please select a chord region and try again.');
      return;
    }

    const planResult = buildChordRegionImportPlan(chordRegions);
    if (!planResult.ok) {
      await showAlert(planResult.error.message);
      return;
    }

    try {
      const result = await runChordRegionImport(track, trackIndex, planResult.plan);
      if (!result) return;
      const affectedRegion = result.affectedRegion;
      if (!onExternalDropComplete) {
        refreshProjectState();
        return;
      }

      const beatsPerBar = timeSignature.numerator;
      const regionUI: RegionUI = {
        id: affectedRegion.getId(),
        trackId: track.getId().toString(),
        trackIndex,
        barNumber: (affectedRegion.getStartFromBeat() / beatsPerBar) + 1,
        length: affectedRegion.getLength() / beatsPerBar,
        name: affectedRegion.getName(),
      };
      onExternalDropComplete(trackIndex, regionUI);
    } catch (error) {
      console.error('[ChordImport] Drop import failed:', error);
      await showAlert('Unable to import the selected chord regions into a MIDI region. Please try again.');
    }
  };

  return (
    <div className="grid-container" ref={gridContainerRef} onMouseDownCapture={startLassoSelection}>
      {/* Playhead */}
      <Playhead context="main-grid" showTriangle={false} />

      {/* Track grids */}
      {tracks.map((track, index) => (
        <TrackGridItem
          key={track.getId()}
          track={track}
          index={index}
          isDragging={draggedTrackIndex === index}
          isDragOver={dragOverTrackIndex === index}
          regions={regions}
          maxBars={maxBars}
          selectedRegionId={selectedRegionId}
          gridContainerRef={gridContainerRef}
          onDoubleClick={handleTrackGridDoubleClick}
          onClick={handleTrackGridClick}
          onRegionResize={handleRegionResize}
          onRegionResizeEnd={handleRegionResizeEnd}
          onRegionDrag={handleRegionDrag}
          onRegionDragEnd={handleRegionDragEnd}
          onRegionFineMoveEnd={handleRegionFineMoveEnd}
          onRegionClick={handleRegionClick}
          onOpenPianoRoll={onOpenPianoRoll}
          onOpenWaveform={onOpenWaveform}
          onOpenSpectrogram={onOpenSpectrogram}
          showHybridButtonForAudio={showHybridButtonForAudio}
          showHybridButtonForMidi={showHybridButtonForMidi}
          hybridButtonExcludedRegionIds={hybridButtonExcludedRegionIds}
          onOpenHybrid={onOpenHybrid}
          allTracks={tracks}
          onKGOneClipDrop={handleExternalDrop}
          onLocalFileDrop={handleLocalFileDrop}
          onChordRegionDrop={handleChordRegionDrop}
          previewRegionStyles={previewRegionStyles}
          setPreviewRegionStyles={setPreviewRegionStyles}
          previewRegionContentStyles={previewRegionContentStyles}
          setPreviewRegionContentStyles={setPreviewRegionContentStyles}
        />
      ))}

      <FileImportModal
        isVisible={showAudioImportModal}
        onClose={() => setShowAudioImportModal(false)}
        onFileImport={handleAudioFileImport}
        acceptedTypes={[...AUDIO_IMPORT_ACCEPTED_TYPES]}
        title="Import Audio"
        description="Drag and drop your audio file here"
      />
      <SelectionBox
        key={lassoRenderTick}
        isSelecting={isLassoSelectingRef.current}
        selectionBox={lassoBoxRef.current}
      />
    </div>
  );
};

export default TrackGridPanel; 
